css:
.deependsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7edf3;
    background: linear-gradient(160deg, #11161d 0%, #1a222d 60%, #232e3c 100%);
    border-radius: 18px;
}

.deependsim-container * {
    box-sizing: border-box;
}

.deependsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0c1218 0%, #20303f 55%, #2c4154 100%);
    color: #f4f7fa;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #2f3e4f;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}

.deependsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: #f4f7fa;
}

.deependsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e8a13a;
    background: rgba(232, 161, 58, 0.12);
    border: 1px solid rgba(232, 161, 58, 0.35);
    padding: 5px 14px;
    border-radius: 999px;
}

.deependsim-subtitle {
    margin: 12px auto 0;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c4d0dc;
}

.deependsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebccb;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.deependsim-period-counter #currentDay,
.deependsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #e8a13a;
}

.deependsim-round-name {
    background: #2a3848;
    color: #e7edf3;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid #3a4d61;
}

.deependsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff8a6b;
    background: rgba(255, 90, 60, 0.12);
    border: 1px solid rgba(255, 90, 60, 0.35);
    padding: 4px 12px;
    border-radius: 999px;
}

.deependsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.deependsim-status-card {
    background: #1b2531;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #2d3c4d;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.30);
    border-top: 4px solid #e8a13a;
}

.deependsim-card-strategy { border-top-color: #4f8cff; }
.deependsim-card-execution { border-top-color: #2fb39a; }
.deependsim-card-talent { border-top-color: #b07cff; }
.deependsim-card-confidence { border-top-color: #e8a13a; }

.deependsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa0b5;
}

.deependsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f4f7fa;
}

.deependsim-card-strategy .deependsim-value { color: #6ba2ff; }
.deependsim-card-execution .deependsim-value { color: #3fd0b4; }
.deependsim-card-talent .deependsim-value { color: #c79bff; }
.deependsim-card-confidence .deependsim-value { color: #f0b25a; }

.deependsim-sublabel {
    font-size: 0.74rem;
    color: #7e92a6;
    line-height: 1.35;
}

.deependsim-kpi-low .deependsim-value { color: #ff6b52; }
.deependsim-kpi-high .deependsim-value { color: #3fd0b4; }

.deependsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0c1218;
    color: #e7edf3;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #2d3c4d;
}

.deependsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0b25a;
}

.deependsim-budget-over #budgetDisplay {
    color: #ff6b52;
}

.deependsim-briefing {
    display: flex;
    gap: 14px;
    background: #1b2531;
    border-left: 5px solid #e8a13a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #2d3c4d;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.28);
}

.deependsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.deependsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f4f7fa;
    margin-bottom: 6px;
}

.deependsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c4d0dc;
}

.deependsim-briefing-text strong { color: #f0b25a; }
.deependsim-briefing-text em { color: #ff8a6b; font-style: italic; }

.deependsim-controls {
    background: #1b2531;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #2d3c4d;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.28);
}

.deependsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f4f7fa;
    border-bottom: 2px solid #2d3c4d;
    padding-bottom: 8px;
}

.deependsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cdd9e5;
    margin: 14px 0 6px;
}

.deependsim-container select,
.deependsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #3a4d61;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #141c25;
    color: #e7edf3;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.deependsim-container select:focus,
.deependsim-container input[type="number"]:focus {
    outline: none;
    border-color: #e8a13a;
    box-shadow: 0 0 0 3px rgba(232, 161, 58, 0.18);
}

.deependsim-container select option {
    background-color: #141c25;
    color: #e7edf3;
}

.deependsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #e8a13a;
}

.deependsim-range-readout,
.deependsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #aebccb;
    margin-top: 4px;
}

.deependsim-range-readout span:last-child,
.deependsim-alloc-readout span:nth-child(2) {
    color: #f0b25a;
    font-weight: 800;
}

.deependsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.deependsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #141c25;
    border: 1px solid #2d3c4d;
    border-radius: 9px;
    padding: 8px 12px;
}

.deependsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #cdd9e5;
}

.deependsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.deependsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.deependsim-container .btn-primary {
    background: linear-gradient(135deg, #c8771f 0%, #e8a13a 100%);
    border: none;
    color: #1a120a;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(232, 161, 58, 0.28);
}

.deependsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.deependsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #3a4d61;
    color: #aebccb;
    background: transparent;
}

.deependsim-coach {
    background: #0c1218;
    color: #d8e2ec;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #2d3c4d;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.deependsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e8a13a;
    margin-bottom: 8px;
}

.deependsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.deependsim-coach-body strong { color: #f0b25a; }
.deependsim-coach-body em { color: #ff8a6b; font-style: italic; }

.deependsim-history,
.deependsim-chart {
    background: #1b2531;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #2d3c4d;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.28);
}

.deependsim-history h3,
.deependsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f4f7fa;
}

.deependsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cdd9e5;
}

.deependsim-container table#usfHistoryTable th {
    background: #141c25;
    color: #e8a13a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2d3c4d;
}

.deependsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #25313f;
}

.deependsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #18212c;
}

.deependsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .deependsim-container {
        padding: 14px;
    }
    .deependsim-header h1 {
        font-size: 1.7rem;
    }
    .deependsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .deependsim-value {
        font-size: 2rem;
    }
    .deependsim-clock {
        margin-left: 0;
    }
    .deependsim-period-counter {
        font-size: 0.88rem;
    }
    .deependsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .deependsim-alloc-row {
        flex-wrap: wrap;
    }
    .deependsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .deependsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) — self-contained, readable on the white modal */
.deependsim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #15263a; }
.deependsim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(21,38,58,0.15); margin-bottom: 16px; }
.deependsim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #1c5b8a; }
.deependsim-cm-score-max { font-size: 18px; font-weight: 600; color: #45607f; margin-left: 2px; }
.deependsim-cm-grade { font-size: 18px; font-weight: 700; color: #15263a; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.deependsim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.deependsim-cm-yes { background: rgba(28,91,138,0.16); color: #164e77; }
.deependsim-cm-no { background: rgba(176,51,37,0.12); color: #b03325; }
.deependsim-cm-warn { background: rgba(180,110,20,0.16); color: #8a5410; }
.deependsim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.deependsim-cm-metric { flex: 1 1 110px; background: #eef1f6; border: 1px solid rgba(21,38,58,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.deependsim-cm-mv { display: block; font-size: 22px; font-weight: 800; color: #15263a; }
.deependsim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #45607f; margin-top: 2px; }
.deependsim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #45607f; margin-bottom: 8px; }
.deependsim-cm-insights { margin: 0; padding-left: 20px; }
.deependsim-cm-insights li { font-size: 14px; line-height: 1.5; color: #22324a; margin-bottom: 8px; }

