(function() {
    'use strict';

    class DeepEndAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Deep End`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (GBP, £M unless stated).
            this.BUDGET_CAP = 3.5;          // £3.5M before a group capital review
            this.FULL_PLAN = 6.2;           // the "do everything" plan exceeds the cap
            this.START_STRATEGY = 20;
            this.START_EXECUTION = 25;
            this.START_TALENT = 30;
            this.START_CONFIDENCE = 40;
            this.WIN_COMPOSITE = 70;        // a reachable "balanced strategic leader" bar
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    strategy: this.START_STRATEGY,
                    execution: this.START_EXECUTION,
                    talent: this.START_TALENT,
                    confidence: this.START_CONFIDENCE,
                    budgetUsed: 0,
                    capitalReview: false,
                    contractLost: false,
                    strategyHistory: [this.START_STRATEGY],
                    executionHistory: [this.START_EXECUTION],
                    talentHistory: [this.START_TALENT],
                    confidenceHistory: [this.START_CONFIDENCE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    root: `both`,
                    intent: `cleanmotion`,
                    mustwin: `unit`,
                    stoplist: 50,
                    posture: `balanced`,
                    external: 1.4,
                    testing: 1.2,
                    engineering: 0.9,
                    commit: `coherent`,
                    leader: `highpotential`,
                    scaffold: 55,
                    authority: `real`,
                    fallback: `checkpoint`,
                    recover: `focused`,
                    coach: `coach`,
                    retention: `targeted`,
                    board: `honest`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const intent = document.getElementById(`intentInput`);
                const mustwin = document.getElementById(`mustwinInput`);
                const stop = document.getElementById(`stoplistInput`);
                if (root) decisions.root = root.value;
                if (intent) decisions.intent = intent.value;
                if (mustwin) decisions.mustwin = mustwin.value;
                if (stop) decisions.stoplist = parseInt(stop.value, 10);
                if (!Number.isFinite(decisions.stoplist) || decisions.stoplist < 0 || decisions.stoplist > 100) {
                    warn(`warn_stoplist_range`); return false;
                }
            } else if (round === 2) {
                const posture = document.getElementById(`postureInput`);
                const commit = document.getElementById(`commitInput`);
                if (posture) decisions.posture = posture.value;
                if (commit) decisions.commit = commit.value;
                const ext = document.getElementById(`externalInput`);
                const test = document.getElementById(`testingInput`);
                const eng = document.getElementById(`engineeringInput`);
                if (ext) decisions.external = parseFloat(ext.value);
                if (test) decisions.testing = parseFloat(test.value);
                if (eng) decisions.engineering = parseFloat(eng.value);
                const parts = [decisions.external, decisions.testing, decisions.engineering];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.external + decisions.testing + decisions.engineering) * 100) / 100;
                if (total > this.BUDGET_CAP + 0.001) {
                    warn(`warn_alloc_overcap`); return false;
                }
                if (total <= 0) {
                    warn(`warn_alloc_zero`); return false;
                }
            } else if (round === 3) {
                const leader = document.getElementById(`leaderInput`);
                const scaffold = document.getElementById(`scaffoldInput`);
                const authority = document.getElementById(`authorityInput`);
                const fallback = document.getElementById(`fallbackInput`);
                if (leader) decisions.leader = leader.value;
                if (scaffold) decisions.scaffold = parseInt(scaffold.value, 10);
                if (authority) decisions.authority = authority.value;
                if (fallback) decisions.fallback = fallback.value;
                if (!Number.isFinite(decisions.scaffold) || decisions.scaffold < 0 || decisions.scaffold > 100) {
                    warn(`warn_scaffold_range`); return false;
                }
            } else if (round === 4) {
                const recover = document.getElementById(`recoverInput`);
                const coach = document.getElementById(`coachInput`);
                const retention = document.getElementById(`retentionInput`);
                const board = document.getElementById(`boardInput`);
                const conviction = document.getElementById(`convictionInput`);
                if (recover) decisions.recover = recover.value;
                if (coach) decisions.coach = coach.value;
                if (retention) decisions.retention = retention.value;
                if (board) decisions.board = board.value;
                if (conviction) decisions.conviction = parseInt(conviction.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Four KPIs move on their deltas. spend = £M committed this round.
            let strategyDelta = 0, executionDelta = 0, talentDelta = 0, confidenceDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the twice-missed launch (capability AND focus) and set a real direction.
                switch (d.root) {
                    case `both`: strategyDelta += 14; executionDelta += 4; coachKey = `coach_r1_root_right`; break;
                    case `capability`: strategyDelta += 4; coachKey = `coach_r1_capability`; break;
                    case `execution`: strategyDelta -= 6; executionDelta -= 2; coachKey = `coach_r1_execution`; break;
                    case `people`: strategyDelta -= 8; confidenceDelta -= 6; coachKey = `coach_r1_people`; break;
                }

                // Strategic intent: a clear, deliverable direction beats both a grand slogan and a budget target.
                switch (d.intent) {
                    case `cleanmotion`: strategyDelta += 14; confidenceDelta += 4; if (d.root === `both`) coachKey = `coach_r1_direction_sharp`; break;
                    case `grand`: strategyDelta += 4; coachKey = `coach_r1_grand`; break;
                    case `budget`: strategyDelta -= 4; coachKey = `coach_r1_budget`; break;
                    case `none`: strategyDelta -= 12; confidenceDelta -= 4; coachKey = `coach_r1_nointent`; break;
                }

                // Must-win: one qualified unit, freed by a stop-list — not "everything at once".
                switch (d.mustwin) {
                    case `unit`: executionDelta += 10; confidenceDelta += 6; break;
                    case `everything`: executionDelta -= 6; strategyDelta -= 2; coachKey = `coach_r1_everything`; break;
                    case `morale`: executionDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r1_morale` : coachKey; break;
                }

                // Stop-list discipline frees capacity for the must-win.
                if (d.stoplist >= 60) { executionDelta += 6; strategyDelta += 4; }
                else if (d.stoplist <= 25) { executionDelta -= 6; confidenceDelta -= 4; coachKey = `coach_r1_nostop`; }

                summaryKey = (d.intent === `cleanmotion` && d.mustwin === `unit` && d.root === `both`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Crisis posture: a disciplined sprint HELD INSIDE a clear direction (visionary + managerial).
                switch (d.posture) {
                    case `balanced`: strategyDelta += 10; executionDelta += 10; confidenceDelta += 8; coachKey = `coach_r2_balanced`; break;
                    case `visiononly`: strategyDelta += 8; executionDelta -= 12; confidenceDelta -= 8; coachKey = `coach_r2_visiononly`; break;
                    case `mgmtonly`: executionDelta += 12; strategyDelta -= 12; confidenceDelta -= 4; coachKey = `coach_r2_mgmtonly`; break;
                }

                // Budget: the capability gap is senior power-electronics expertise — fund it or stay stuck.
                spend = d.external + d.testing + d.engineering;
                if (d.external >= 1.0) { executionDelta += 8; if (d.posture === `balanced` && coachKey === `coach_r2_balanced`) coachKey = `coach_r2_capgap_funded`; }
                else if (d.external <= 0.2) { executionDelta -= 8; confidenceDelta -= 4; coachKey = `coach_r2_capgap_starved`; }
                else { executionDelta += 3; }
                if (d.testing >= 0.8) { executionDelta += 5; }
                else if (d.testing <= 0.2) { executionDelta -= 4; }
                if (d.engineering >= 0.6) { executionDelta += 3; }

                // Commitments: one coherent, credible story beats over-promising or two-faced telling.
                switch (d.commit) {
                    case `coherent`: confidenceDelta += 12; strategyDelta += 4; break;
                    case `overpromise`: confidenceDelta -= 12; coachKey = `coach_r2_overpromise`; break;
                    case `split`: confidenceDelta -= 16; coachKey = `coach_r2_split`; break;
                }

                summaryKey = (d.posture === `balanced` && d.external >= 1.0 && d.commit === `coherent`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // The stretch assignment: develop a leader by stretching them, WITH a scaffold.
                if (d.leader === `highpotential`) {
                    talentDelta += 6;
                    if (d.scaffold >= 55) { talentDelta += 18; executionDelta += 6; coachKey = `coach_r3_stretch_scaffold`; }
                    else if (d.scaffold <= 30) { talentDelta -= 12; executionDelta -= 8; coachKey = `coach_r3_stretch_noscaffold`; }
                    else { talentDelta += 6; coachKey = `coach_r3_stretch_thin`; }
                } else { // deputy — safe, no development, decent short-term delivery.
                    talentDelta -= 8; executionDelta += 6; confidenceDelta += 2; coachKey = `coach_r3_deputy`;
                    if (d.scaffold >= 55) { talentDelta += 3; }
                }

                // Authority: a real, guard-railed mandate develops; micromanaging or abandoning does not.
                switch (d.authority) {
                    case `real`: talentDelta += 8; executionDelta += 4; break;
                    case `micromanage`: talentDelta -= 8; executionDelta -= 4; coachKey = (d.leader === `highpotential` && coachKey === `coach_r3_stretch_scaffold`) ? `coach_r3_micromanage` : coachKey; break;
                    case `abandon`: talentDelta -= 6; executionDelta -= 6; coachKey = (coachKey === `coach_default` || coachKey === `coach_r3_stretch_scaffold`) ? `coach_r3_abandon` : coachKey; break;
                }

                // Halfway checkpoint and fallback: planned support beats a silent swap-out.
                switch (d.fallback) {
                    case `checkpoint`: talentDelta += 8; confidenceDelta += 4; break;
                    case `none`: talentDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_nofallback` : coachKey; break;
                    case `swap`: talentDelta -= 8; coachKey = `coach_r3_swap`; break;
                }

                summaryKey = (d.leader === `highpotential` && d.scaffold >= 55 && d.authority === `real`) ? `sum_r3_good` : (d.leader === `deputy` ? `sum_r3_safe` : `sum_r3_weak`);
            } else if (round === 4) {
                // Deliver, develop and win confidence — without abandoning the direction.
                switch (d.recover) {
                    case `focused`: executionDelta += 12; confidenceDelta += 6; coachKey = `coach_r4_focused`; break;
                    case `descope`: executionDelta -= 6; confidenceDelta -= 10; ds.contractLost = ds.confidence + confidenceDelta < 45; coachKey = `coach_r4_descope`; break;
                    case `overspend`: executionDelta += 8; confidenceDelta -= 12; spend = Math.max(spend, (this.BUDGET_CAP - ds.budgetUsed) + 1.5); ds.capitalReview = true; coachKey = `coach_r4_overspend`; break;
                }

                // Coach, don't rescue: a setback survived builds a leader; a rescue un-builds one.
                switch (d.coach) {
                    case `coach`: talentDelta += 16; confidenceDelta += 6; coachKey = (d.recover === `focused`) ? `coach_r4_coach` : coachKey; break;
                    case `rescue`: talentDelta -= 14; executionDelta += 4; confidenceDelta -= 2; coachKey = `coach_r4_rescue`; break;
                    case `abandon`: talentDelta -= 18; confidenceDelta -= 6; coachKey = `coach_r4_abandon`; break;
                }

                // Retention move on the remaining flight-risk engineers (£0.9M exposure).
                switch (d.retention) {
                    case `targeted`: talentDelta += 8; confidenceDelta += 6; break;
                    case `counteroffer`: talentDelta -= 2; confidenceDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_counteroffer` : coachKey; break;
                    case `ignore`: talentDelta -= 10; confidenceDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_ignore` : coachKey; break;
                }

                // Board read: link delivery to strategy honestly; over-claiming burns credibility.
                switch (d.board) {
                    case `honest`: strategyDelta += 10; confidenceDelta += 12; coachKey = (d.coach === `coach` && d.recover === `focused`) ? `coach_r4_board_honest` : coachKey; break;
                    case `overclaim`: confidenceDelta -= 14; strategyDelta += 2; coachKey = `coach_r4_overclaim`; break;
                    case `gantt`: strategyDelta -= 8; confidenceDelta -= 4; coachKey = `coach_r4_gantt`; break;
                }

                // Conviction nudges talent and strategy.
                const convNudge = Math.round((d.conviction - 60) / 8);
                talentDelta += convNudge;
                strategyDelta += convNudge;

                summaryKey = (d.recover === `focused` && d.coach === `coach` && d.board === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Budget accounting (capped display at the £3.5M authority unless a capital review is triggered).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;
            if (ds.budgetUsed > this.BUDGET_CAP + 0.001) ds.capitalReview = true;

            // Apply deltas, clamp 0–100.
            ds.strategy = Math.max(0, Math.min(100, ds.strategy + strategyDelta));
            ds.execution = Math.max(0, Math.min(100, ds.execution + executionDelta));
            ds.talent = Math.max(0, Math.min(100, ds.talent + talentDelta));
            ds.confidence = Math.max(0, Math.min(100, ds.confidence + confidenceDelta));

            ds.strategyHistory.push(Math.round(ds.strategy));
            ds.executionHistory.push(Math.round(ds.execution));
            ds.talentHistory.push(Math.round(ds.talent));
            ds.confidenceHistory.push(Math.round(ds.confidence));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            const composite = Math.round(ds.strategy * 0.25 + ds.execution * 0.30 + ds.talent * 0.20 + ds.confidence * 0.25);

            return {
                period: state.currentPeriod,
                strategy: Math.round(ds.strategy),
                strategyDelta: Math.round(strategyDelta),
                execution: Math.round(ds.execution),
                executionDelta: Math.round(executionDelta),
                talent: Math.round(ds.talent),
                talentDelta: Math.round(talentDelta),
                confidence: Math.round(ds.confidence),
                confidenceDelta: Math.round(confidenceDelta),
                composite: composite,
                budgetUsed: ds.budgetUsed,
                capitalReview: ds.capitalReview,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

