            if (scaffold && scaffoldReadout) {
                scaffoldReadout.textContent = scaffold.value;
                scaffold.addEventListener(`input`, function() { scaffoldReadout.textContent = scaffold.value; });
            }

            // Recovery spend live total against the £3.5M cap.
            const self = this;
            const allocIds = [`externalInput`, `testingInput`, `engineeringInput`];
