                if (spendReadout) spendReadout.style.color = (total > self.BUDGET_CAP + 0.001) ? `#ff6b52` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

