        // Composite (0-100) VERBATIM from v1.0.0 getPerformanceSummary; written to
        // domainState.performance.overallScore each period for the reporting/grading layer.
        _composite(ds) {
            var strategy = Math.round(ds.strategy || 0);
            var execution = Math.round(ds.execution || 0);
            var talent = Math.round(ds.talent || 0);
            var confidence = Math.round(ds.confidence || 0);
            return Math.round(strategy * 0.25 + execution * 0.30 + talent * 0.20 + confidence * 0.25);
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const strategy = Math.round(ds.strategy);
            const execution = Math.round(ds.execution);
            const talent = Math.round(ds.talent);
            const confidence = Math.round(ds.confidence);
            const composite = this._composite(ds);

            const balanced = strategy >= 60 && execution >= 60;   // visionary AND managerial
            const developed = talent >= 60;
            // The apex label demands a genuinely STRETCHED-and-developed leader. The safe
            // deputy path tops out at talent 70 (Common Error #3 — "never stretching"), while a
            // properly scaffolded-and-coached high-potential lands 86+. A 75 bar lets every
            // legitimate stretch run keep the apex label yet denies it to the play-safe deputy.
            const stretchDeveloped = talent >= 75;
            const trusted = confidence >= 60;

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_depth`;
            if (composite >= this.WIN_COMPOSITE && balanced && stretchDeveloped && trusted) performanceKey = `grade_strategic`;
            else if (composite >= this.WIN_COMPOSITE && balanced) performanceKey = `grade_mandate`;
            else if (execution >= 65 && strategy < 45) performanceKey = `grade_manager`;
            else if (strategy >= 65 && execution < 45) performanceKey = `grade_speech`;
            else if (composite >= 50) performanceKey = `grade_survived`;
            const performance = T(performanceKey);

            const insights = [];
            if (composite >= this.WIN_COMPOSITE && balanced && stretchDeveloped && trusted) insights.push(window.mySimulation.t(`insight_strategic`));
            else if (execution >= 65 && strategy < 45) insights.push(window.mySimulation.t(`insight_manager`));
            else if (strategy >= 65 && execution < 45) insights.push(window.mySimulation.t(`insight_speech`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!developed) insights.push(window.mySimulation.t(`insight_notalent`));
            else if (talent >= 70) insights.push(window.mySimulation.t(`insight_madeleader`));
            if (!trusted) insights.push(window.mySimulation.t(`insight_lowconfidence`));
            if (ds.capitalReview) insights.push(window.mySimulation.t(`insight_capitalreview`));
            if (ds.contractLost) insights.push(window.mySimulation.t(`insight_contractlost`));

            return {
                strategy: strategy,
                execution: execution,
                talent: talent,
                confidence: confidence,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performanceKey: performanceKey,
                capitalReview: ds.capitalReview,
                contractLost: ds.contractLost,
                balanced: balanced,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var ok = (s.performanceKey === 'grade_strategic' || s.performanceKey === 'grade_mandate');
            var badge = ok
                ? '<span class="deependsim-cm-badge deependsim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="deependsim-cm-badge deependsim-cm-no">' + T('cm_missed') + '</span>';
            var failBadge = (s.capitalReview || s.contractLost)
                ? '<span class="deependsim-cm-badge deependsim-cm-warn">' + T('cm_failstate_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="deependsim-cm-metric"><span class="deependsim-cm-mv">' + Math.round(s.strategy || 0) + '</span><span class="deependsim-cm-ml">' + T('cm_m_strategy') + '</span></div>'
                + '<div class="deependsim-cm-metric"><span class="deependsim-cm-mv">' + Math.round(s.execution || 0) + '</span><span class="deependsim-cm-ml">' + T('cm_m_execution') + '</span></div>'
                + '<div class="deependsim-cm-metric"><span class="deependsim-cm-mv">' + Math.round(s.talent || 0) + '</span><span class="deependsim-cm-ml">' + T('cm_m_talent') + '</span></div>'
                + '<div class="deependsim-cm-metric"><span class="deependsim-cm-mv">' + Math.round(s.confidence || 0) + '</span><span class="deependsim-cm-ml">' + T('cm_m_confidence') + '</span></div>';
            return ''
                + '<div class="deependsim-completion">'
                +   '<div class="deependsim-cm-head">'
                +     '<div class="deependsim-cm-score">' + score + '<span class="deependsim-cm-score-max">/100</span></div>'
                +     '<div class="deependsim-cm-grade">' + grade + ' ' + badge + failBadge + '</div>'
                +   '</div>'
                +   '<div class="deependsim-cm-metrics">' + metrics + '</div>'
                +   '<div class="deependsim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="deependsim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
