            if (state.currentPeriod >= 2 && ds.strategy < 35 && ds.execution >= 55) return window.mySimulation.t(`hint_manager`);
            if (state.currentPeriod >= 2 && ds.execution < 35 && ds.strategy >= 55) return window.mySimulation.t(`hint_speech`);
            if (state.currentPeriod >= 3 && ds.talent < 35) return window.mySimulation.t(`hint_talent`);
            if (ds.confidence < 35) return window.mySimulation.t(`hint_confidence`);
            if (ds.strategy >= 60 && ds.execution >= 60 && ds.talent >= 60 && ds.confidence >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

